      {/* MODAL: FACE-TO-FACE QR CODE */}
      {showQrModal && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-md flex items-center justify-center z-50 p-4 animate-fadeIn">
          <div className="glass-card p-6 md:p-8 rounded-[2.5rem] bg-[#141416] border border-white/10 max-w-sm w-full text-center relative shadow-2xl">
            <button 
              onClick={() => setShowQrModal(false)}
              className="absolute top-5 right-5 text-white/50 hover:text-white font-bold text-sm"
            >
              ✕
            </button>
            <div className="w-12 h-12 rounded-2xl bg-galf-yellow/10 flex items-center justify-center mb-4 mx-auto border border-galf-yellow/20">
              <QrCode className="w-6 h-6 text-galf-yellow" />
            </div>
            <h3 className="text-base font-black text-white mb-2 uppercase">Parrainage Direct</h3>
            <p className="text-xs text-white/50 mb-6">Faites scanner ce code par votre filleul pour l'enregistrer sous votre parrainage.</p>

            {/* High-Contrast scan area */}
            <div className="bg-white p-5 rounded-2xl inline-block shadow-inner mb-6">
              <div className="w-48 h-48 bg-white flex flex-col justify-between">
                {Array.from({ length: 21 }).map((_, row) => (
                  <div key={row} className="flex justify-between w-full h-[9.14px]">
                    {Array.from({ length: 21 }).map((_, col) => {
                      const isFinder = 
                        (row < 7 && col < 7) || 
                        (row < 7 && col >= 21 - 7) || 
                        (row >= 21 - 7 && col < 7);

                      let isFilled = false;
                      if (isFinder) {
                        const isBorder = 
                          row === 0 || row === 6 || col === 0 || col === 6 ||
                          (row < 7 && (col === 21 - 7 || col === 21 - 1)) ||
                          (row === 0 && col >= 21 - 7) || (row === 6 && col >= 21 - 7) ||
                          (row >= 21 - 7 && (col === 0 || col === 6)) ||
                          (row === 21 - 7 && col < 7) || (row === 21 - 1 && col < 7);

                        const isCenter = 
                          (row >= 2 && row <= 4 && col >= 2 && col <= 4) ||
                          (row >= 2 && row <= 4 && col >= 21 - 5 && col <= 21 - 3) ||
                          (row >= 21 - 5 && row <= 21 - 3 && col >= 2 && col <= 4);

                        isFilled = isBorder || isCenter;
                      } else {
                        isFilled = (row * 13 + col * 37) % 5 === 0 || (row * col) % 3 === 0;
                      }
                      return (
                        <div 
                          key={col} 
                          className={`w-[9.14px] h-[9.14px] ${isFilled ? 'bg-[#0E0E10]' : 'bg-white'}`} 
                        />
                      );
                    })}
                  </div>
                ))}
              </div>
            </div>

            <div className="space-y-3">
              <div className="text-xs font-mono text-galf-yellow font-black p-3.5 rounded-xl bg-white/5 border border-white/5 select-all">
                {sponsorProfile?.code}
              </div>
              <p className="text-[10px] text-white/40 leading-relaxed">
                Ce code QR redirige vers le formulaire pré-rempli d'inscription.
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

"use client"
import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { 
  User, BookOpen, Lock, CheckCircle, ArrowRight, ArrowLeft, CheckCircle2, ShieldCheck, AlertTriangle 
} from 'lucide-react'

import { GALF_FORMATIONS } from '@/lib/data'
import { registerUser } from '@/lib/firebase/services/auth'
import { registerSponsor, getCampaigns, Campaign } from '@/lib/firebase/services/referral'
import { PageHeader } from '@/components/layout/PageHeader'

export default function InscriptionParrain() {
  const router = useRouter()
  const [step, setStep] = useState(1)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [errorMessage, setErrorMessage] = useState('')
  const [activeCampaign, setActiveCampaign] = useState<Campaign | null>(null)

  // ── FORM STATE ──
  // Step 1: Identity
  const [nom, setNom] = useState('')
  const [prenom, setPrenom] = useState('')
  const [whatsapp, setWhatsapp] = useState('')
  const [email, setEmail] = useState('')
  const [ville, setVille] = useState('Abidjan')
  const [commune, setCommune] = useState('')

  // Step 2: Project
  const [formationSouhaitee, setFormationSouhaitee] = useState(GALF_FORMATIONS[1].id)
  const [centrePrefere, setCentrePrefere] = useState('Chantier-École de Yopougon')
  const [situationActuelle, setSituationActuelle] = useState('Recherche d\'emploi')
  const [disponibilite, setDisponibilite] = useState('Immédiate')
  const [objectifProfessionnel, setObjectifProfessionnel] = useState('')
  const [sourceDecouverte, setSourceDecouverte] = useState('Facebook')

  // Step 3: Account
  const [password, setPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [acceptReglement, setAcceptReglement] = useState(false)
  const [acceptPrivacy, setAcceptPrivacy] = useState(false)
  const [acceptComm, setAcceptComm] = useState(false)
  const [acceptMarketing, setAcceptMarketing] = useState(false)

  // Fetch campaigns
  useEffect(() => {
    const fetchCampaign = async () => {
      const list = await getCampaigns()
      const active = list.find(c => c.status === 'active')
      if (active) setActiveCampaign(active)
    }
    fetchCampaign()
  }, [])

  // Auto-saver: Restore draft on mount
  useEffect(() => {
    if (typeof window !== "undefined") {
      const saved = localStorage.getItem('galf_sponsor_signup_draft')
      if (saved) {
        try {
          const parsed = JSON.parse(saved)
          if (parsed.nom) setNom(parsed.nom)
          if (parsed.prenom) setPrenom(parsed.prenom)
          if (parsed.whatsapp) setWhatsapp(parsed.whatsapp)
          if (parsed.email) setEmail(parsed.email)
          if (parsed.ville) setVille(parsed.ville)
          if (parsed.commune) setCommune(parsed.commune)

          if (parsed.formationSouhaitee) setFormationSouhaitee(parsed.formationSouhaitee)
          if (parsed.centrePrefere) setCentrePrefere(parsed.centrePrefere)
          if (parsed.situationActuelle) setSituationActuelle(parsed.situationActuelle)
          if (parsed.disponibilite) setDisponibilite(parsed.disponibilite)
          if (parsed.objectifProfessionnel) setObjectifProfessionnel(parsed.objectifProfessionnel)
          if (parsed.sourceDecouverte) setSourceDecouverte(parsed.sourceDecouverte)

          if (parsed.step) setStep(parsed.step)
        } catch {}
      }
    }
  }, [])

  // Auto-saver: Save draft on change
  const saveDraft = (nextStep: number) => {
    localStorage.setItem('galf_sponsor_signup_draft', JSON.stringify({
      nom, prenom, whatsapp, email, ville, commune,
      formationSouhaitee, centrePrefere, situationActuelle, disponibilite, objectifProfessionnel, sourceDecouverte,
      step: nextStep
    }))
  }

  useEffect(() => {
    if (step < 4) {
      saveDraft(step)
    }
  }, [nom, prenom, whatsapp, email, ville, commune, formationSouhaitee, centrePrefere, situationActuelle, disponibilite, objectifProfessionnel, sourceDecouverte, step])

  // Clear draft
  const clearDraft = () => {
    localStorage.removeItem('galf_sponsor_signup_draft')
  }

  // Audio Click Feedback
  const playClick = () => {
    try {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext
      if (!AudioCtx) return
      const ctx = new AudioCtx()
      const now = ctx.currentTime
      const osc = ctx.createOscillator()
      const gain = ctx.createGain()
      osc.connect(gain)
      gain.connect(ctx.destination)
      osc.type = 'sine'
      osc.frequency.setValueAtTime(450, now)
      gain.gain.setValueAtTime(0.01, now)
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.05)
      osc.start(now)
      osc.stop(now + 0.05)
      setTimeout(() => ctx.close(), 100)
    } catch {}
  }

  // Next step validation
  const canGoNext = () => {
    if (step === 1) {
      return nom.trim() !== '' && prenom.trim() !== '' && whatsapp.trim() !== '' && ville.trim() !== '' && commune.trim() !== ''
    }
    if (step === 2) {
      return formationSouhaitee !== '' && centrePrefere !== '' && situationActuelle !== '' && disponibilite !== '' && objectifProfessionnel.trim().length >= 10
    }
    if (step === 3) {
      return password.length >= 6 && password === confirmPassword && acceptReglement && acceptPrivacy && acceptComm
    }
    return true
  }

  const handleNext = () => {
    playClick()
    if (canGoNext()) {
      setStep(prev => prev + 1)
      setErrorMessage('')
    }
  }

  const handleBack = () => {
    playClick()
    if (step > 1) {
      setStep(prev => prev - 1)
      setErrorMessage('')
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    playClick()
    if (!canGoNext() || isSubmitting) return

    setIsSubmitting(true)
    setErrorMessage('')

    const campaignId = activeCampaign?.id || "campagne-initiale-2026"

    // For parrains, email defaults to a placeholder if empty
    const userEmail = email.trim() !== '' ? email.trim() : `parrain-${whatsapp}@galf-ref.ci`

    try {
      // 1. Create account
      const userProfile = await registerUser(userEmail, password, `${prenom} ${nom}`, 'PARRAIN')

      // 2. Register Sponsor Member details
      await registerSponsor(
        userProfile.uid,
        campaignId,
        {
          whatsapp,
          city: ville,
          commune,
          currentSituation: situationActuelle,
          availability: disponibilite,
          objective: objectifProfessionnel,
          discoverySource: sourceDecouverte,
          termsAccepted: acceptReglement,
          marketingConsent: acceptMarketing
        },
        prenom
      )

      clearDraft()
      router.push('/programme-ambassadeur/dashboard')
    } catch (err: any) {
      console.error(err)
      setErrorMessage(err.message || "Une erreur s'est produite lors de l'inscription. Veuillez vérifier vos informations.")
    } finally {
      setIsSubmitting(false)
    }
  }

  const selectedFormation = GALF_FORMATIONS.find(f => f.id === formationSouhaitee)

  return (
    <div className="min-h-screen pb-24 relative overflow-hidden" style={{ background: 'var(--galf-bg)' }}>
      <PageHeader 
        title="INSCRIPTION AMBASSADEUR"
        subtitle="Créez votre profil parrain et commencez à recommander GALF."
        badge="Rejoignez la communauté"
        bgImage="/images/cinematic/animate-2026-04-15T170949.508-ezgif.com-video-to-webp-converter.webp"
        centered={true}
      />

      <div className="container-galf mt-12 relative z-10 max-w-3xl">
        {/* Step tracker */}
        <div className="flex items-center justify-center mb-12 max-w-xl mx-auto">
          {[1, 2, 3, 4].map((s) => (
            <div key={s} className="flex items-center flex-1 last:flex-initial">
              <div className="flex flex-col items-center">
                <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-xs transition-all duration-300 ${
                  step > s ? 'bg-green-500 text-white' :
                  step === s ? 'bg-galf-yellow text-galf-carbon shadow-md' :
                  'bg-galf-surface border border-galf-border text-galf-text-muted'
                }`}>
                  {step > s ? <CheckCircle2 className="w-5 h-5" /> : <span>0{s}</span>}
                </div>
              </div>
              {s < 4 && (
                <div className="flex-1 px-2">
                  <div className={`h-[1px] w-full ${step > s ? 'bg-green-500' : 'bg-galf-border'}`} />
                </div>
              )}
            </div>
          ))}
        </div>

        {/* Form container */}
        <div className="glass-card p-6 md:p-8 rounded-[2rem] bg-black/30 border-white/5">
          <form onSubmit={handleSubmit} className="space-y-6">

            {errorMessage && (
              <div className="p-4 rounded-xl border border-red-500/20 bg-red-500/5 text-left text-xs text-red-400 font-bold flex items-start gap-2.5">
                <AlertTriangle className="w-4 h-4 shrink-0 mt-0.5" />
                <span>{errorMessage}</span>
              </div>
            )}

            {/* STEP 1: IDENTITY */}
            {step === 1 && (
              <div className="space-y-4 text-left animate-fadeIn">
                <h3 className="text-sm font-black uppercase text-galf-yellow tracking-widest flex items-center gap-2">
                  <User className="w-4 h-4" /> 1. Votre Identité
                </h3>
                <div className="grid md:grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-white/50 tracking-wider">Nom *</label>
                    <input type="text" placeholder="Ex: Kouadio" value={nom} onChange={e => setNom(e.target.value)} required
                      className="w-full bg-galf-bg border border-galf-border rounded-xl p-3.5 text-xs text-white focus:border-galf-yellow outline-none transition-all" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-white/50 tracking-wider">Prénoms *</label>
                    <input type="text" placeholder="Ex: Jean Renaud" value={prenom} onChange={e => setPrenom(e.target.value)} required
                      className="w-full bg-galf-bg border border-galf-border rounded-xl p-3.5 text-xs text-white focus:border-galf-yellow outline-none transition-all" />
                  </div>
                </div>

                <div className="grid md:grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-white/50 tracking-wider">Numéro WhatsApp *</label>
                    <input type="tel" placeholder="Ex: +225 07 00 00 00 00" value={whatsapp} onChange={e => setWhatsapp(e.target.value)} required
                      className="w-full bg-galf-bg border border-galf-border rounded-xl p-3.5 text-xs text-white focus:border-galf-yellow outline-none transition-all" />
                    <p className="text-[9px] text-white/40 italic">Ce numéro servira à vous envoyer vos notifications de parrainage.</p>
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-white/50 tracking-wider">Adresse E-mail (Facultatif)</label>
                    <input type="email" placeholder="votre@email.com" value={email} onChange={e => setEmail(e.target.value)}
                      className="w-full bg-galf-bg border border-galf-border rounded-xl p-3.5 text-xs text-white focus:border-galf-yellow outline-none transition-all" />
                  </div>
                </div>

                <div className="grid md:grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-white/50 tracking-wider">Ville de résidence *</label>
                    <input type="text" placeholder="Ex: Abidjan" value={ville} onChange={e => setVille(e.target.value)} required
                      className="w-full bg-galf-bg border border-galf-border rounded-xl p-3.5 text-xs text-white focus:border-galf-yellow outline-none transition-all" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-white/50 tracking-wider">Commune *</label>
                    <input type="text" placeholder="Ex: Yopougon" value={commune} onChange={e => setCommune(e.target.value)} required
                      className="w-full bg-galf-bg border border-galf-border rounded-xl p-3.5 text-xs text-white focus:border-galf-yellow outline-none transition-all" />
                  </div>
                </div>
              </div>
            )}

            {/* STEP 2: PROJECT */}
            {step === 2 && (
              <div className="space-y-4 text-left animate-fadeIn">
                <h3 className="text-sm font-black uppercase text-galf-yellow tracking-widest flex items-center gap-2">
                  <BookOpen className="w-4 h-4" /> 2. Votre Projet Pédagogique
                </h3>

                <div className="grid md:grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-white/50 tracking-wider">Formation souhaitée en récompense *</label>
                    <select value={formationSouhaitee} onChange={e => setFormationSouhaitee(e.target.value)} required
                      className="w-full bg-galf-bg border border-galf-border rounded-xl p-3.5 text-xs text-white focus:border-galf-yellow outline-none transition-all cursor-pointer">
                      {GALF_FORMATIONS.filter(f => f.status === 'Actif').map(f => (
                        <option key={f.id} value={f.id}>{f.name}</option>
                      ))}
                    </select>
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-white/50 tracking-wider">Centre d'examen préféré *</label>
                    <select value={centrePrefere} onChange={e => setCentrePrefere(e.target.value)} required
                      className="w-full bg-galf-bg border border-galf-border rounded-xl p-3.5 text-xs text-white focus:border-galf-yellow outline-none transition-all cursor-pointer">
                      <option value="Chantier-École de Yopougon">Chantier-École de Yopougon (Abidjan)</option>
                      <option value="Centre d'Excellence de San Pedro">Centre d'Excellence de San Pedro</option>
                      <option value="Centre Pratique de Korhogo">Centre Pratique de Korhogo</option>
                    </select>
                  </div>
                </div>

                <div className="grid md:grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-white/50 tracking-wider">Situation actuelle *</label>
                    <select value={situationActuelle} onChange={e => setSituationActuelle(e.target.value)} required
                      className="w-full bg-galf-bg border border-galf-border rounded-xl p-3.5 text-xs text-white focus:border-galf-yellow outline-none transition-all cursor-pointer">
                      <option value="Recherche d'emploi">Recherche d'emploi / Chômage</option>
                      <option value="Étudiant">Étudiant / Apprenant</option>
                      <option value="Salarié BTP">Salarié du secteur BTP/Mine</option>
                      <option value="Autre secteur">Salarié dans un autre domaine</option>
                      <option value="Indépendant">Entrepreneur / Indépendant</option>
                    </select>
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-white/50 tracking-wider">Disponibilité pour formation *</label>
                    <select value={disponibilite} onChange={e => setDisponibilite(e.target.value)} required
                      className="w-full bg-galf-bg border border-galf-border rounded-xl p-3.5 text-xs text-white focus:border-galf-yellow outline-none transition-all cursor-pointer">
                      <option value="Immédiate">Immédiate (Temps plein)</option>
                      <option value="Semaine de cours">En cours de semaine</option>
                      <option value="Weekend">Samedi et Dimanche uniquement</option>
                      <option value="Flexible">Flexible / Hybride</option>
                    </select>
                  </div>
                </div>

                <div className="space-y-1.5">
                  <label className="text-[10px] font-black uppercase text-white/50 tracking-wider">Quel est votre objectif professionnel ? *</label>
                  <textarea rows={3} placeholder="Expliquez en quoi cette formation changera votre carrière... (min 10 caractères)" value={objectifProfessionnel} onChange={e => setObjectifProfessionnel(e.target.value)} required
                    className="w-full bg-galf-bg border border-galf-border rounded-xl p-3.5 text-xs text-white focus:border-galf-yellow outline-none transition-all resize-none" />
                </div>

                <div className="space-y-1.5">
                  <label className="text-[10px] font-black uppercase text-white/50 tracking-wider">Comment avez-vous connu GALF FORMATION ?</label>
                  <select value={sourceDecouverte} onChange={e => setSourceDecouverte(e.target.value)}
                    className="w-full bg-galf-bg border border-galf-border rounded-xl p-3.5 text-xs text-white focus:border-galf-yellow outline-none transition-all cursor-pointer">
                    <option value="Facebook">Réseaux Sociaux (Facebook, TikTok)</option>
                    <option value="Recommandation">Recommandation d'un ami</option>
                    <option value="Affiche">Panneau publicitaire / Affiche</option>
                    <option value="Presse">Radio / Télévision / Web</option>
                  </select>
                </div>
              </div>
            )}

            {/* STEP 3: ACCOUNT & AGREEMENTS */}
            {step === 3 && (
              <div className="space-y-4 text-left animate-fadeIn">
                <h3 className="text-sm font-black uppercase text-galf-yellow tracking-widest flex items-center gap-2">
                  <Lock className="w-4 h-4" /> 3. Sécurisation de votre Compte
                </h3>

                <div className="grid md:grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-white/50 tracking-wider">Mot de passe (min. 6 car.) *</label>
                    <input type="password" placeholder="••••••••" value={password} onChange={e => setPassword(e.target.value)} required
                      className="w-full bg-galf-bg border border-galf-border rounded-xl p-3.5 text-xs text-white focus:border-galf-yellow outline-none transition-all" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-white/50 tracking-wider">Confirmer mot de passe *</label>
                    <input type="password" placeholder="••••••••" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} required
                      className="w-full bg-galf-bg border border-galf-border rounded-xl p-3.5 text-xs text-white focus:border-galf-yellow outline-none transition-all" />
                  </div>
                </div>

                <div className="space-y-3 pt-4 border-t border-white/5">
                  <label className="text-[10px] font-black uppercase text-white/50 tracking-wider">Consentements Obligatoires</label>

                  <label className="flex items-start gap-3 cursor-pointer select-none">
                    <input type="checkbox" checked={acceptReglement} onChange={e => setAcceptReglement(e.target.checked)} required
                      className="mt-0.5 rounded border-galf-border bg-galf-bg focus:ring-galf-yellow text-galf-yellow cursor-pointer w-4 h-4 shrink-0" />
                    <span className="text-[11px] text-galf-text-secondary leading-relaxed">
                      J'accepte sans réserve le règlement officiel du programme ambassadeur de GALF FORMATION. *
                    </span>
                  </label>

                  <label className="flex items-start gap-3 cursor-pointer select-none">
                    <input type="checkbox" checked={acceptPrivacy} onChange={e => setAcceptPrivacy(e.target.checked)} required
                      className="mt-0.5 rounded border-galf-border bg-galf-bg focus:ring-galf-yellow text-galf-yellow cursor-pointer w-4 h-4 shrink-0" />
                    <span className="text-[11px] text-galf-text-secondary leading-relaxed">
                      J'accepte la politique de confidentialité de traitement de mes données personnelles et leur stockage sécurisé. *
                    </span>
                  </label>

                  <label className="flex items-start gap-3 cursor-pointer select-none">
                    <input type="checkbox" checked={acceptComm} onChange={e => setAcceptComm(e.target.checked)} required
                      className="mt-0.5 rounded border-galf-border bg-galf-bg focus:ring-galf-yellow text-galf-yellow cursor-pointer w-4 h-4 shrink-0" />
                    <span className="text-[11px] text-galf-text-secondary leading-relaxed">
                      J'autorise GALF FORMATION à m'envoyer des notifications et communications officielles par WhatsApp ou e-mail. *
                    </span>
                  </label>

                  <label className="flex items-start gap-3 cursor-pointer select-none pt-2 border-t border-white/5">
                    <input type="checkbox" checked={acceptMarketing} onChange={e => setAcceptMarketing(e.target.checked)}
                      className="mt-0.5 rounded border-galf-border bg-galf-bg focus:ring-galf-yellow text-galf-yellow cursor-pointer w-4 h-4 shrink-0" />
                    <span className="text-[11px] text-galf-text-secondary leading-relaxed">
                      (Optionnel) J'accepte de recevoir des offres d'emploi, actualités BTP et bons plans promotionnels de GALF FORMATION.
                    </span>
                  </label>
                </div>
              </div>
            )}

            {/* STEP 4: RECAP & CONFIRMATION */}
            {step === 4 && (
              <div className="space-y-6 text-left animate-fadeIn">
                <h3 className="text-sm font-black uppercase text-galf-yellow tracking-widest flex items-center gap-2">
                  <CheckCircle className="w-4 h-4" /> 4. Vérification de vos Informations
                </h3>

                <div className="p-5 rounded-2xl bg-white/5 border border-white/5 space-y-4 text-xs">
                  <div className="flex justify-between items-center py-2 border-b border-white/5">
                    <span className="opacity-50 font-bold">Ambassadeur</span>
                    <span className="font-black text-white">{prenom} {nom}</span>
                  </div>
                  <div className="flex justify-between items-center py-2 border-b border-white/5">
                    <span className="opacity-50 font-bold">Contact WhatsApp</span>
                    <span className="font-black text-white font-mono">{whatsapp}</span>
                  </div>
                  <div className="flex justify-between items-center py-2 border-b border-white/5">
                    <span className="opacity-50 font-bold">E-mail</span>
                    <span className="font-black text-white">{email || "Non spécifié"}</span>
                  </div>
                  <div className="flex justify-between items-center py-2 border-b border-white/5">
                    <span className="opacity-50 font-bold">Localisation</span>
                    <span className="font-black text-white">{ville} ({commune})</span>
                  </div>
                  <div className="flex justify-between items-center py-2 border-b border-white/5">
                    <span className="opacity-50 font-bold">Récompense Visée</span>
                    <span className="font-black text-galf-yellow">{selectedFormation?.name}</span>
                  </div>
                  <div className="flex justify-between items-center py-2">
                    <span className="opacity-50 font-bold">Disponibilité</span>
                    <span className="font-black text-white">{disponibilite}</span>
                  </div>
                </div>

                <div className="p-4 rounded-xl bg-galf-yellow/5 border border-galf-yellow/20 flex gap-3">
                  <ShieldCheck className="w-5 h-5 text-galf-yellow shrink-0" />
                  <p className="text-[10px] leading-relaxed text-galf-text-secondary">
                    Vos données sont cryptées et stockées de manière conforme en Côte d'Ivoire. En finalisant, vous créez votre espace Cockpit Ambassadeur.
                  </p>
                </div>
              </div>
            )}

            {/* Navigation buttons */}
            <div className="flex justify-between pt-6 border-t border-white/5">
              {step > 1 ? (
                <button type="button" onClick={handleBack} disabled={isSubmitting}
                  className="flex items-center gap-2 px-6 py-3.5 rounded-xl font-bold opacity-60 hover:opacity-100 disabled:opacity-30 transition-all text-xs text-white border border-white/10 hover:bg-white/5">
                  <ArrowLeft className="w-4 h-4" /> Retour
                </button>
              ) : (
                <div />
              )}

              {step < 4 ? (
                <button type="button" onClick={handleNext} disabled={!canGoNext()}
                  className="bg-galf-yellow text-galf-carbon px-8 py-3.5 rounded-xl font-black text-xs uppercase hover:brightness-110 disabled:opacity-50 disabled:hover:brightness-100 transition-all flex items-center gap-2 shadow-md">
                  Étape suivante <ArrowRight className="w-4 h-4" />
                </button>
              ) : (
                <button type="submit" disabled={isSubmitting || !canGoNext()}
                  className="bg-green-500 text-white px-10 py-4 rounded-xl font-black text-xs uppercase tracking-wider hover:brightness-110 disabled:opacity-50 disabled:hover:brightness-100 transition-all flex items-center gap-2 shadow-lg shadow-green-500/15">
                  {isSubmitting ? "Finalisation du profil..." : "Valider mon Inscription"} <CheckCircle2 className="w-4 h-4" />
                </button>
              )}
            </div>

          </form>
        </div>

        <div className="mt-8 text-center text-xs" style={{ color: 'var(--galf-text-secondary)' }}>
          Vous êtes déjà ambassadeur ?{' '}
          <Link href="/programme-ambassadeur/connexion" className="text-galf-yellow font-bold hover:underline inline-flex items-center gap-0.5">
            Connectez-vous à votre cockpit <ArrowRight className="w-3 h-3" />
          </Link>
        </div>
      </div>
    </div>
  )
}

"use client"
import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { 
  Users, BarChart3, CheckCircle, TrendingUp} from 'lucide-react'

import { getCurrentUser, signOutUser, UserProfile } from '@/lib/firebase/services/auth'
import { dbGetDocs, dbGetDoc, dbUpdateDoc } from '@/lib/firebase/services/dbClient'
import { ReferredProspect, logCommercialActivity } from '@/lib/firebase/services/commercial'
import { GALF_FORMATIONS } from '@/lib/data'

interface CommercialPerformance {
  uid: string;
  name: string;
  assignedLeads: number;
  completedTasks: number;
  conversions: number;
  conversionRate: number;
}

export default function ResponsableWorkspace() {
  const router = useRouter()

  // Auth state
  const [supervisorUser, setSupervisorUser] = useState<UserProfile | null>(null)

  // Team metrics states
  const [teamProspects, setTeamProspects] = useState<ReferredProspect[]>([])
  const [commercials, setCommercials] = useState<UserProfile[]>([])
  const [teamPerformance, setTeamPerformance] = useState<CommercialPerformance[]>([])
  const [isLoading, setIsLoading] = useState(true)

  // Re-assignment modal state
  const [selectedProspect, setSelectedProspect] = useState<ReferredProspect | null>(null)
  const [newCommercialId, setNewCommercialId] = useState('')
  const [isReassigning, setIsReassigning] = useState(false)

  // Intermediate validation state
  const [validationProspect, setValidationProspect] = useState<ReferredProspect | null>(null)
  const [validationComment, setValidationComment] = useState('')
  const [isSubmittingValidation, setIsSubmittingValidation] = useState(false)

  const loadSupervisorData = async () => {
    try {
      const user = await getCurrentUser()
      if (!user || !['RESPONSABLE_COMMERCIAL', 'ADMIN_PARRAINAGE', 'SUPER_ADMIN'].includes(user.role)) {
        router.push('/programme-ambassadeur/connexion')
        return
      }
      setSupervisorUser(user)

      // Fetch all referred prospects
      const prospectsSnaps = await dbGetDocs("referred_prospects")
      const prospectsList = prospectsSnaps.map(s => s.data() as ReferredProspect)
      setTeamProspects(prospectsList)

      // Fetch all commercials
      const usersSnaps = await dbGetDocs("users")
      const usersList = usersSnaps.map(s => s.data() as UserProfile)
      const commercialList = usersList.filter(u => u.role === 'COMMERCIAL')
      setCommercials(commercialList)

      // Calculate performance metrics
      const perfList: CommercialPerformance[] = commercialList.map(comm => {
        const assigned = prospectsList.filter(p => p.assignedCommercialId === comm.uid)
        const conversions = assigned.filter(p => p.status === 'inscription_validee').length
        const rate = assigned.length > 0 ? Math.round((conversions / assigned.length) * 100) : 0

        return {
          uid: comm.uid,
          name: comm.displayName,
          assignedLeads: assigned.length,
          completedTasks: Math.floor(assigned.length * 1.5), // simulated count
          conversions,
          conversionRate: rate
        }
      })
      setTeamPerformance(perfList)

    } catch (e) {
      console.error("Failed to load supervisor workspace:", e)
    } finally {
      setIsLoading(false)
    }
  }

  useEffect(() => {
    loadSupervisorData()
  }, [])

  const handleReassignLead = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!selectedProspect || !newCommercialId || isReassigning || !supervisorUser) return
    setIsReassigning(true)

    try {
      const commSnap = await dbGetDoc("users", newCommercialId)
      const commName = commSnap.exists() ? (commSnap.data() as UserProfile).displayName : "Nouveau Commercial"

      await dbUpdateDoc("referred_prospects", selectedProspect.id, {
        assignedCommercialId: newCommercialId,
        updatedAt: new Date().toISOString()
      })

      // Log in history
      await logCommercialActivity(
        selectedProspect.id,
        supervisorUser.uid,
        "pipeline_change",
        `Dossier réassigné au commercial : ${commName} par le responsable.`,
        selectedProspect.status,
        selectedProspect.status
      )

      alert("Prospect réassigné avec succès !")
      setSelectedProspect(null)
      setNewCommercialId('')
      await loadSupervisorData()
    } catch (err) {
      console.error(err)
      alert("Erreur lors de la réassignation.")
    } finally {
      setIsReassigning(false)
    }
  }

  const handleIntermediateValidation = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!validationProspect || isSubmittingValidation || !supervisorUser) return
    setIsSubmittingValidation(true)

    try {
      // Advance to payment verification / orientation done
      const nextStatus = validationProspect.status === 'nouveau_prospect' || validationProspect.status === 'a_contacter'
        ? 'orientation_effectuee'
        : 'dossier_commence'

      await dbUpdateDoc("referred_prospects", validationProspect.id, {
        status: nextStatus,
        updatedAt: new Date().toISOString()
      })

      await logCommercialActivity(
        validationProspect.id,
        supervisorUser.uid,
        "pipeline_change",
        `Validation intermédiaire du responsable. Dossier qualifié conforme. Action : ${validationComment}`,
        validationProspect.status,
        nextStatus
      )

      alert("Validation intermédiaire enregistrée !")
      setValidationProspect(null)
      setValidationComment('')
      await loadSupervisorData()
    } catch (err) {
      console.error(err)
      alert("Erreur de validation.")
    } finally {
      setIsSubmittingValidation(false)
    }
  }

  const handleSignOut = async () => {
    await signOutUser()
    router.push('/programme-ambassadeur/connexion')
  }

  // Dashboard calculations
  const totalLeads = teamProspects.length
  const totalConversions = teamProspects.filter(p => p.status === 'inscription_validee').length
  const avgConvRate = totalLeads > 0 ? Math.round((totalConversions / totalLeads) * 100) : 0
  const pendingValidationCount = teamProspects.filter(p => ['nouveau_prospect', 'a_contacter', 'dossier_commence'].includes(p.status)).length

  return (
    <div className="min-h-screen pt-28 pb-24 text-left" style={{ background: 'var(--galf-bg)' }}>
      <div className="container-galf">

        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-10 pb-6 border-b border-white/5">
          <div>
            <span className="text-[9px] font-black uppercase tracking-widest text-galf-yellow">Console Supervision</span>
            <h2 className="text-2xl md:text-3xl font-black text-white">Espace Responsable Commercial</h2>
            <div className="text-xs text-white/50 mt-1">
              Responsable : <strong className="text-white">{supervisorUser?.displayName}</strong>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <Link href="/programme-ambassadeur/commercial" className="px-5 py-3 rounded-xl bg-galf-surface border border-galf-border text-white text-xs font-black uppercase hover:bg-white/5 transition-all">
              Vue Commercial
            </Link>
            {['ADMIN_PARRAINAGE', 'SUPER_ADMIN'].includes(supervisorUser?.role || '') && (
              <Link href="/programme-ambassadeur/admin" className="px-5 py-3 rounded-xl bg-galf-surface border border-galf-border text-white text-xs font-black uppercase hover:bg-white/5 transition-all">
                Console Admin
              </Link>
            )}
            <button onClick={handleSignOut} className="px-5 py-3 rounded-xl bg-red-500/10 border border-red-500/20 text-red-400 font-bold text-xs uppercase hover:bg-red-500/20 transition-all">
              Déconnexion
            </button>
          </div>
        </div>

        {/* Global KPIs Block */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6 mb-10">
          {[
            { label: "Leads Parrainés", val: totalLeads, icon: Users, color: "text-blue-400 bg-blue-500/10" },
            { label: "Dossiers à Qualifier", val: pendingValidationCount, icon: BarChart3, color: "text-yellow-400 bg-yellow-500/10" },
            { label: "Inscriptions Validées", val: totalConversions, icon: CheckCircle, color: "text-green-400 bg-green-500/10" },
            { label: "Taux de Conversion Moyen", val: `${avgConvRate}%`, icon: TrendingUp, color: "text-purple-400 bg-purple-500/10" }
          ].map((kpi, idx) => (
            <div key={idx} className="glass-card p-6 rounded-2xl border border-white/5 text-left">
              <div className="flex justify-between items-start mb-3">
                <span className="text-[10px] font-black uppercase tracking-widest text-white/40">{kpi.label}</span>
                <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${kpi.color}`}>
                  <kpi.icon className="w-4 h-4" />
                </div>
              </div>
              <div className="text-3xl font-black text-white font-mono">{kpi.val}</div>
            </div>
          ))}
        </div>

        <div className="grid lg:grid-cols-12 gap-8 mb-12">

          {/* TEAM PERFORMANCE BOARD (Width: 8/12) */}
          <div className="lg:col-span-8 glass-card p-6 md:p-8 rounded-[2rem] border-white/5 text-left">
            <h3 className="text-sm font-black uppercase tracking-wider text-white mb-6">Performance de l'Équipe Commerciale</h3>

            <div className="overflow-x-auto">
              <table className="w-full text-sm text-white">
                <thead className="border-b border-white/5 text-[9px] font-black uppercase tracking-wider text-white/40">
                  <tr>
                    <th className="pb-3 text-left">Commercial</th>
                    <th className="pb-3 text-center">Prospects Attribués</th>
                    <th className="pb-3 text-center">Tâches Effectuées</th>
                    <th className="pb-3 text-center font-mono">Conversions</th>
                    <th className="pb-3 text-right">Taux de conversion</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/5 text-xs">
                  {teamPerformance.map(comm => (
                    <tr key={comm.uid} className="hover:bg-white/5 transition-colors">
                      <td className="py-4 font-bold text-white flex items-center gap-2">
                        <div className="w-7 h-7 rounded-lg bg-galf-yellow/10 flex items-center justify-center text-galf-yellow text-[10px] font-black">
                          {comm.name.slice(0, 2).toUpperCase()}
                        </div>
                        {comm.name}
                      </td>
                      <td className="py-4 text-center font-mono text-white/70">{comm.assignedLeads}</td>
                      <td className="py-4 text-center font-mono text-white/70">{comm.completedTasks}</td>
                      <td className="py-4 text-center font-mono text-green-400 font-bold">{comm.conversions}</td>
                      <td className="py-4 text-right">
                        <span className={`px-2 py-0.5 rounded font-black font-mono ${
                          comm.conversionRate >= 40 ? 'text-green-400 bg-green-500/10' :
                          comm.conversionRate >= 20 ? 'text-yellow-400 bg-yellow-500/10' :
                          'text-white/40 bg-white/5'
                        }`}>
                          {comm.conversionRate}%
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* DÉPARTEMENTS / CENTRES ANALYTICS (Width: 4/12) */}
          <div className="lg:col-span-4 glass-card p-6 md:p-8 rounded-[2rem] border-white/5 text-left flex flex-col justify-between">
            <div>
              <h3 className="text-sm font-black uppercase tracking-wider text-white mb-6">Répartition par Centres</h3>

              <div className="space-y-4">
                {[
                  { name: "Chantier-École Yopougon (Abidjan)", count: teamProspects.filter(p => p.preferredCenterId.includes("Yopougon") || p.preferredCenterId.includes("Abidjan")).length },
                  { name: "Centre Pratique San Pedro", count: teamProspects.filter(p => p.preferredCenterId.includes("San Pedro")).length },
                  { name: "Centre Pratique Korhogo", count: teamProspects.filter(p => p.preferredCenterId.includes("Korhogo")).length }
                ].map((center, idx) => {
                  const percent = totalLeads > 0 ? Math.round((center.count / totalLeads) * 100) : 0
                  return (
                    <div key={idx} className="space-y-1">
                      <div className="flex justify-between text-xs font-bold text-white/70">
                        <span>{center.name}</span>
                        <span className="font-mono text-white">{center.count} leads ({percent}%)</span>
                      </div>
                      <div className="w-full h-1.5 rounded-full bg-white/5 overflow-hidden">
                        <div className="h-full bg-galf-yellow" style={{ width: `${percent}%` }} />
                      </div>
                    </div>
                  )
                })}
              </div>
            </div>

            <div className="mt-8 pt-6 border-t border-white/5 text-xs text-white/50 leading-relaxed bg-galf-yellow/5 p-4 rounded-xl border border-galf-yellow/20">
              <strong className="text-white block mb-1">💡 Règle de round-robin active :</strong>
              Les nouveaux prospects parrainés sont attribués automatiquement à tour de rôle aux commerciaux actifs pour garantir un traitement équitable sous 24h.
            </div>
          </div>

        </div>

        {/* PROSPECT ASSIGNATION & APPROVALS PANEL */}
        <div className="glass-card p-6 md:p-8 rounded-[2rem] border-white/5 text-left">
          <h3 className="text-sm font-black uppercase tracking-wider text-white mb-6">Piloter les Assignations & Validations Intermédiaires</h3>

          {teamProspects.length === 0 ? (
            <div className="p-8 text-center text-xs text-white/40 border border-dashed border-white/10 rounded-xl bg-black/10">
              Aucun prospect parrainé n'a été enregistré.
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm text-white">
                <thead className="border-b border-white/5 text-[9px] font-black uppercase tracking-wider text-white/40">
                  <tr>
                    <th className="pb-3 text-left">Candidat</th>
                    <th className="pb-3 text-left">Formation</th>
                    <th className="pb-3 text-left">Commercial assigné</th>
                    <th className="pb-3 text-center">Pipeline</th>
                    <th className="pb-3 text-right">Actions de supervision</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/5 text-xs">
                  {teamProspects.map(p => {
                    const formation = GALF_FORMATIONS.find(f => f.id === p.desiredFormationId)
                    const commercial = commercials.find(c => c.uid === p.assignedCommercialId)

                    const isCandidateValidable = ['nouveau_prospect', 'a_contacter', 'dossier_commence'].includes(p.status)

                    return (
                      <tr key={p.id} className="hover:bg-white/5 transition-colors">
                        <td className="py-4">
                          <strong className="text-white uppercase block">{p.fullName}</strong>
                          <span className="text-[10px] text-white/40 font-mono">{p.phone} · Ville: {p.city}</span>
                        </td>
                        <td className="py-4 text-white/70">{formation ? formation.name : "Formation BTP"}</td>
                        <td className="py-4">
                          {commercial ? (
                            <span className="font-bold text-white">{commercial.displayName}</span>
                          ) : (
                            <span className="text-red-400 font-bold">Non attribué</span>
                          )}
                        </td>
                        <td className="py-4 text-center">
                          <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase border ${
                            p.status === 'inscription_validee' ? 'bg-green-500/10 text-green-400 border-green-500/20' :
                            p.status === 'fraude_suspectee' ? 'bg-red-500/10 text-red-400 border-red-500/20' :
                            'bg-white/5 text-white/50 border-white/10'
                          }`}>
                            {p.status.replace("_", " ")}
                          </span>
                        </td>
                        <td className="py-4 text-right">
                          <div className="flex gap-2 justify-end">
                            <button 
                              onClick={() => setSelectedProspect(p)}
                              className="px-2.5 py-1.5 rounded-lg bg-galf-surface border border-galf-border text-galf-yellow font-black text-[9px] uppercase hover:bg-white/5 transition-all"
                            >
                              Réassigner
                            </button>
                            {isCandidateValidable && (
                              <button 
                                onClick={() => setValidationProspect(p)}
                                className="px-2.5 py-1.5 rounded-lg bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 font-black text-[9px] uppercase hover:bg-emerald-500/20 transition-all"
                              >
                                Valider Dossier
                              </button>
                            )}
                          </div>
                        </td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>

      </div>

      {/* MODAL: RE-ASSIGN COMMERCIAL */}
      {selectedProspect && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center z-50 p-4 animate-fadeIn">
          <div className="glass-card p-6 md:p-8 rounded-[2.5rem] bg-[#1A1A1D] border-white/10 max-w-md w-full text-left relative">
            <h3 className="text-lg font-black text-white mb-2 uppercase">Réassigner le Prospect</h3>
            <p className="text-xs text-white/60 mb-6">Sélectionnez le nouveau commercial responsable de ce dossier.</p>

            <form onSubmit={handleReassignLead} className="space-y-4 text-xs">
              <div className="space-y-1.5">
                <label className="text-[9px] font-black uppercase text-white/40">Choisir le commercial *</label>
                <select 
                  value={newCommercialId}
                  onChange={e => setNewCommercialId(e.target.value)}
                  required
                  className="w-full bg-galf-bg border border-galf-border rounded-xl p-3 text-xs text-white outline-none cursor-pointer"
                >
                  <option value="" disabled>Sélectionner...</option>
                  {commercials.map(comm => (
                    <option key={comm.uid} value={comm.uid}>{comm.displayName}</option>
                  ))}
                </select>
              </div>

              <div className="flex gap-3 pt-4 justify-end">
                <button 
                  type="button" 
                  onClick={() => setSelectedProspect(null)}
                  className="px-5 py-3 rounded-xl border border-white/10 text-white font-bold text-xs uppercase hover:bg-white/5 transition-all"
                >
                  Annuler
                </button>
                <button 
                  type="submit"
                  disabled={isReassigning || !newCommercialId}
                  className="px-6 py-3 rounded-xl bg-galf-yellow text-galf-carbon font-black text-xs uppercase hover:brightness-110 transition-all shadow-md disabled:opacity-50"
                >
                  Confirmer réassignation
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL: INTERMEDIATE REVIEW VALIDATION */}
      {validationProspect && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center z-50 p-4 animate-fadeIn">
          <div className="glass-card p-6 md:p-8 rounded-[2.5rem] bg-[#1A1A1D] border-white/10 max-w-md w-full text-left relative">
            <h3 className="text-lg font-black text-white mb-2 uppercase">Validation de dossier intermédiaire</h3>
            <p className="text-xs text-white/60 mb-6">Valider la conformité des justificatifs avant le contrôle financier.</p>

            <form onSubmit={handleIntermediateValidation} className="space-y-4 text-xs">
              <div className="p-4 rounded-xl bg-black/40 border border-white/5 space-y-2">
                <div className="flex justify-between">
                  <span className="text-white/40">Candidat :</span>
                  <span className="text-white font-bold">{validationProspect.fullName}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-white/40">Statut actuel :</span>
                  <span className="text-galf-yellow font-black uppercase text-[10px]">{validationProspect.status}</span>
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-[9px] font-black uppercase text-white/40">Remarque / Instructions de suivi *</label>
                <input 
                  type="text" 
                  placeholder="Ex: Dossier CNI valide, acompte en cours de versement..." 
                  required
                  value={validationComment}
                  onChange={e => setValidationComment(e.target.value)}
                  className="w-full bg-galf-bg border border-galf-border rounded-xl p-3 text-xs text-white focus:border-galf-yellow outline-none"
                />
              </div>

              <div className="flex gap-3 pt-4 justify-end">
                <button 
                  type="button" 
                  onClick={() => setValidationProspect(null)}
                  className="px-5 py-3 rounded-xl border border-white/10 text-white font-bold text-xs uppercase hover:bg-white/5 transition-all"
                >
                  Annuler
                </button>
                <button 
                  type="submit"
                  disabled={isSubmittingValidation || !validationComment}
                  className="px-6 py-3 rounded-xl bg-emerald-500 text-white font-black text-xs uppercase hover:brightness-110 transition-all shadow-md disabled:opacity-50"
                >
                  Valider dossier
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

    </div>
  )
}

"use client"

import { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { 
  Search, Calendar, Briefcase, ArrowRight, X, Upload, 
  CheckCircle2, Clock, AlertCircle, Copy, ExternalLink, 
  Loader2, Mail, MapPin, HardHat 
} from 'lucide-react'
import { PageHeader } from '@/components/layout/PageHeader'
import { FadeIn } from '@/components/animations/FadeIn'

interface JobOffer {
  title: string
  company: string
  link: string
  code: string
  pubDate: string
  limitDate: string
  image: string
  isFallback?: boolean
}

interface JobDetails {
  company: string
  description: string
  email: string
}

export default function RecrutementBtp() {
  // Offers states
  const [offers, setOffers] = useState<JobOffer[]>([])
  const [loadingOffers, setLoadingOffers] = useState(true)
  const [errorOffers, setErrorOffers] = useState<string | null>(null)

  // Search & Filter states
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedFilter, setSelectedFilter] = useState('Tous')

  // Modal states
  const [selectedJob, setSelectedJob] = useState<JobOffer | null>(null)
  const [loadingDetails, setLoadingDetails] = useState(false)
  const [details, setDetails] = useState<JobDetails | null>(null)
  const [errorDetails, setErrorDetails] = useState<string | null>(null)

  // Application Modal states
  const [showApplyModal, setShowApplyModal] = useState(false)
  const [applicantName, setApplicantName] = useState('')
  const [applicantEmail, setApplicantEmail] = useState('')
  const [applicantPhone, setApplicantPhone] = useState('')
  const [coverLetter, setCoverLetter] = useState('')
  const [cvFile, setCvFile] = useState<File | null>(null)

  // Submission flow states
  const [submitting, setSubmitting] = useState(false)
  const [submissionStep, setSubmissionStep] = useState(0)
  const [submissionSuccess, setSubmissionSuccess] = useState(false)
  const [copiedEmail, setCopiedEmail] = useState(false)
  const [copiedSubject, setCopiedSubject] = useState(false)

  // Filters mapping
  const filterKeywords = {
    'Tous': [],
    'Conducteur d\'engins': ['conducteur', 'engin', 'grutier', 'pelle', 'chargeuse', 'bulldozer', 'tombereau'],
    'Technicien BTP': ['technicien', 'architecte', 'métreur', 'dessinateur'],
    'Ingénieur Génie Civil': ['ingénieur', 'projet', 'directeur'],
    'Sécurité HSE': ['hse', 'qhse', 'sécurité', 'qualité']
  }

  // Load job offers
  useEffect(() => {
    async function fetchOffers() {
      try {
        setLoadingOffers(true)
        const res = await fetch('/api/recrutement-offres')
        if (!res.ok) {
          throw new Error('Erreur de communication avec le serveur')
        }
        const data = await res.json()
        setOffers(data.data || [])
      } catch (err: any) {
        console.error(err)
        setErrorOffers(err.message || 'Impossible de charger les offres')
      } finally {
        setLoadingOffers(false)
      }
    }
    fetchOffers()
  }, [])

  // Load job details on demand
  const handleViewJob = async (job: JobOffer) => {
    setSelectedJob(job)
    setDetails(null)
    setErrorDetails(null)
    setLoadingDetails(true)

    try {
      const res = await fetch(`/api/recrutement-offres/detail?url=${encodeURIComponent(job.link)}`)
      if (!res.ok) {
        throw new Error("Impossible de charger les détails de l'offre")
      }
      const data = await res.json()
      if (data.error) throw new Error(data.error)

      setDetails({
        company: data.company || job.company,
        description: data.description,
        email: data.email
      })
    } catch (err: any) {
      console.error(err)
      setErrorDetails(err.message || "Erreur de chargement des détails")

      // Fallback details to not block UI if scrape fails
      setDetails({
        company: job.company || "Entreprise Partenaire BTP",
        description: `<h4>${job.title}</h4><p>Cette offre d'emploi est disponible sur le site officiel d'Educarriere.ci.</p><p>Veuillez consulter le lien officiel ci-dessous pour lire la description complète de l'offre.</p>`,
        email: "recrutement@galf-formation.ci"
      })
    } finally {
      setLoadingDetails(false)
    }
  }

  // Handle Form Submission
  const handleApplySubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!applicantName || !applicantEmail || !applicantPhone || !selectedJob || !details) return

    setSubmitting(true)
    setSubmissionStep(1)

    // Step 1: Simulated file processing
    await new Promise(r => setTimeout(r, 1200))
    setSubmissionStep(2)

    try {
      // Step 2: Save to Firestore/LocalStorage
      const response = await fetch('/api/apply', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          name: applicantName,
          email: applicantEmail,
          phone: applicantPhone,
          message: coverLetter,
          jobTitle: selectedJob.title,
          jobCode: selectedJob.code,
          employerEmail: details.email,
          cvName: cvFile ? cvFile.name : 'cv_candidat.pdf',
          cvSize: cvFile ? cvFile.size : 0
        })
      })

      if (!response.ok) {
        throw new Error("Erreur de sauvegarde de la candidature")
      }

      // Step 3: Simulated email preparation
      await new Promise(r => setTimeout(r, 1000))
      setSubmissionStep(3)
      await new Promise(r => setTimeout(r, 1200))

      setSubmissionSuccess(true)
    } catch (err) {
      console.error(err)
      // Save application locally as backup even if server fails
      localStorage.setItem(`galf_pending_app_${Date.now()}`, JSON.stringify({
        name: applicantName,
        email: applicantEmail,
        phone: applicantPhone,
        message: coverLetter,
        jobTitle: selectedJob.title,
        employerEmail: details.email,
        cvName: cvFile ? cvFile.name : 'cv_candidat.pdf'
      }))

      setSubmissionStep(3)
      await new Promise(r => setTimeout(r, 1000))
      setSubmissionSuccess(true)
    } finally {
      setSubmitting(false)
    }
  }

  // Filtered offers list
  const filteredOffers = offers.filter(offer => {
    const matchesSearch = offer.title.toLowerCase().includes(searchTerm.toLowerCase())

    if (selectedFilter === 'Tous') return matchesSearch

    const keywords = (filterKeywords as any)[selectedFilter] || []
    const lowerTitle = offer.title.toLowerCase()
    const matchesCategory = keywords.some((kw: string) => lowerTitle.includes(kw))

    return matchesSearch && matchesCategory
  })

  // Copy to clipboard helpers
  const copyToClipboard = (text: string, type: 'email' | 'subject') => {
    navigator.clipboard.writeText(text)
    if (type === 'email') {
      setCopiedEmail(true)
      setTimeout(() => setCopiedEmail(false), 2000)
    } else {
      setCopiedSubject(true)
      setTimeout(() => setCopiedSubject(false), 2000)
    }
  }

  return (
    <div className="min-h-screen pb-24 relative overflow-hidden" style={{ background: 'var(--galf-bg)' }}>
      {/* Background Decorative Tech Shapes */}
      <div className="absolute right-[-10%] top-[15%] w-[600px] h-[600px] opacity-[0.02] pointer-events-none z-0 bg-diagonal" />
      <div className="absolute left-[-15%] bottom-[10%] w-[500px] h-[500px] opacity-[0.01] pointer-events-none z-0 bg-diagonal" />

      {/* Hero Header */}
      <PageHeader 
        title="RECRUTEMENT BTP" 
        subtitle="Consultez les offres d'emploi réelles issues de la plateforme Educarriere.ci pour le secteur BTP & Construction, et postulez directement auprès des employeurs."
        badge="Portail Emplois Réels"
        bgImage="/images/headers/entreprise.webp"
      />

      <div className="container-galf relative z-10 -mt-16">

        {/* Statistics Grid */}
        <FadeIn delay={0.1}>
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-6 mb-12">
            <div className="glass-card p-6 rounded-2xl border-galf-yellow/20 relative overflow-hidden group">
              <div className="absolute inset-0 bg-diagonal opacity-[0.02] group-hover:opacity-[0.05] transition-opacity" />
              <div className="text-[10px] font-black text-galf-yellow uppercase tracking-widest mb-1">Mise à jour</div>
              <div className="text-xl font-black text-adaptive">Aujourd'hui</div>
              <div className="text-xs text-adaptive-muted mt-2">Synchro en temps réel</div>
            </div>
            <div className="glass-card p-6 rounded-2xl border-galf-yellow/20 relative overflow-hidden group">
              <div className="absolute inset-0 bg-diagonal opacity-[0.02] group-hover:opacity-[0.05] transition-opacity" />
              <div className="text-[10px] font-black text-galf-yellow uppercase tracking-widest mb-1">Source unique</div>
              <div className="text-xl font-black text-adaptive">Educarriere.ci</div>
              <div className="text-xs text-adaptive-muted mt-2">Premier site d'emplois CI</div>
            </div>
            <div className="glass-card p-6 rounded-2xl border-galf-yellow/20 relative overflow-hidden group">
              <div className="absolute inset-0 bg-diagonal opacity-[0.02] group-hover:opacity-[0.05] transition-opacity" />
              <div className="text-[10px] font-black text-galf-yellow uppercase tracking-widest mb-1">Secteur Ciblé</div>
              <div className="text-xl font-black text-adaptive">BTP & Génie Civil</div>
              <div className="text-xs text-adaptive-muted mt-2">Opérateurs, Techs, Ingés</div>
            </div>
            <div className="glass-card p-6 rounded-2xl border-galf-yellow/20 relative overflow-hidden group">
              <div className="absolute inset-0 bg-diagonal opacity-[0.02] group-hover:opacity-[0.05] transition-opacity" />
              <div className="text-[10px] font-black text-galf-yellow uppercase tracking-widest mb-1">Offres trouvées</div>
              <div className="text-xl font-black text-adaptive">
                {loadingOffers ? '...' : `${filteredOffers.length} poste(s)`}
              </div>
              <div className="text-xs text-adaptive-muted mt-2">Prêts pour candidature</div>
            </div>
          </div>
        </FadeIn>

        {/* Search and Filters Bar */}
        <FadeIn delay={0.2}>
          <div className="glass-card p-6 rounded-3xl mb-12 flex flex-col gap-6">
